    ('text="Corporativo, mas dentro da família Smiles." highlight="dentro da família Smiles."', 'text="Corporate, but part of the Smiles family." highlight="part of the Smiles family."'),
    ('text="Identidade do grupo, regras de negócio claras." highlight="regras de negócio claras."', 'text="Group identity, clear business rules." highlight="clear business rules."'),
