# palavras que denunciam texto em PT esquecido (fora de nomes próprios)
PT = re.compile(r'\b(não|são|você|está|também|página|usuári|então|então|cadastro|treino|resultado|decisões|desafio|Conferir|Próximo|mais|para quem|com o|da |dos |das )\b')

missing = False
for rel, pairs in PAGES.items():
    src = open(os.path.join(ROOT, 'src/pages', rel), encoding='utf8').read()
    out = src
    for a, b in COMMON + pairs:
        if a not in out:
            if pairs and (a, b) in pairs:
                print(f'[{rel}] trecho não encontrado: {a[:70]}…'); missing = True
            continue
        out = out.replace(a, b)
    out = out.replace('from "../', 'from "../../')
    # checa o que sobrou em português no conteúdo (ignora o bloco <style>)
    body = out.split('<style>')[0]
    for i, line in enumerate(body.splitlines(), 1):
        s = line.strip()
        if s.startswith('//') or s.startswith('import'): continue
        if PT.search(s):
            print(f'[{rel}:{i}] possível PT: {s[:110]}'); missing = True
    dst = os.path.join(ROOT, 'src/pages/en', rel)
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    open(dst, 'w', encoding='utf8').write(out)
if missing: sys.exit(1)
print('ok')
